namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// The fight loop (M3 3.1 lane fa), read by the headless host's fight scenario and the game's bsd-fight leg; parsed by
    /// src/Lifestone.Client/Session/Scenarios/FightOptions.cs (<c>FightOptions.FromArguments</c>).
    /// </summary>
    public static OptionGroup Fight() => new("Fight loop", "main scene and headless host",
    [
        new("--fight-kills", "N", "How many kills end the fight loop (0 or more, default 1; 0 is no kill limit and needs --fight-minutes): the Black Spawn Den fight of the mage stops at the Nth 0x01AD kill notice. A bad value fails the headless run and the game's bsd-fight leg; the game leg's buff top-up ignores the --buff-* options (it uses their defaults)."),
        new("--fight-seconds", "S", "The most session-clock seconds the fight loop may take from its first cast stage (default 300); past it the fight fails loudly with the counts. With --fight-minutes the limit is the larger of the two."),
        new("--fight-minutes", "M", "The minutes after which the fight loop ends CLEANLY with the kills it made (0 to 1440, default 0: off), unlike --fight-seconds, which is a failure limit. With --fight-kills 0 the fight runs to these minutes."),
        new("--fight-max-level", "L", "The highest Flame Bolt level the fight loop may choose (1 to 7, default 7): the level is the highest the spellbook holds whose cast chance reaches the threshold, capped here (M5 D26: VI at level 80). The level is chosen again when the buffed War Magic or the character's level changes."),
        new("--fight-storeys-min", "N", "The storeys the fight loop's tour visits before it stays on one (1 to 16, default 1; M5 item 2 g6, D40): after one kill on a storey the tour leaves it for the next storey of the ground's profile until N distinct storeys are visited, then it leaves a storey only when no hunted slot of it stands. The tour walks the profile's storeys in order, down and back up, to the nearest cell with a standing hunted slot, and turns back for the arrival's storey when that storey's earliest slot comes due within the walk back plus a margin (the respawn schedule: each slot's death plus its generator's delay, up to the generator's next tick). The fight's line reports storeys_visited=, basement_entries=, returns=, slots_standing=, legs_recovered= (the failed legs the walk went on from), kills_unpaired= (the kills the respawn schedule paired to no slot) and slots_expired= (the dead slots taken as standing with no create seen) (report-only). With 2 or more the fight leg's review frames (first, bolt, hit, kill) wait for their trigger on a storey other than the arrival's."),
        new("--fight-defend-forget-s", "S", "How long the fight keeps fighting a creature that attacked the player after its last attack (0 to 600 session-clock seconds, default 20; 0 turns self-defence off; Lifestone's own bound, M5 item 7 F4). A living creature that hits, misses or casts a hostile spell at the player (a damage or evasion notice, a spell line naming it) becomes the fight's target at once, before the profile's targets and whatever the profile says of it (avoided, no-go, outside the level band), until it is dead, gone from the object table or quiet for this long; then the profile's targets resume. The fight walks (the existing line rule) only when it has no clear line, never into a no-go cell. The fight's line reports defended=<kills of such creatures> (report-only)."),
        new("--fight-defend-hold-s", "S", "How long the fight holds still for an attacker it cannot cast at from where it stands, in a no-go cell (0 to 600 session-clock seconds, default 30; 0 holds without a bound; Lifestone's own bound, M5 item 7 F15). While it holds it heals (Heal Self) whenever the health is under the drain line (--fight-drain-under); after this long the attacker is dropped for the profile's targets, logged once, and is not fought back at again while it stays in the object table."),
        new("--fight-opener-tries", "N", "The most casts of a target's opener when it is resisted or fizzles (0 to 10, default 3; 0 turns openers off; Lifestone's own number, M5 item 7 F8, the owner's D89). A hunting-ground profile may name an opener for a target (the den's Tusker Slave: Fire Vulnerability Other; its Tusker Guard none): on a new target the fight casts it once, at the highest level the ground's spell plan, the spellbook, the cast chance and the pack's scarabs allow, then the bolts; a target already under half its health skips it. Each target logs one opener line and the verdict carries openers=sent:n,landed:n,resisted:n,skipped:n (report-only)."),
        new("--fight-ground", "KEY", "The hunting ground the fight loop, its walks, the death loop's checks and the journeys run in (default black-spawn-den-aluvian): the key of a dungeon profile under Session/Grounds/profiles (M5 item 2 g2b, D46). The fight teleports to the profile's arrival, fights the creatures it lists as targets in its walkable cells, and walks its tour; entering one of its no-go cells stops the walk. An unknown key, or a key that is not a dungeon, fails the headless run and the game's legs at once, naming the known keys."),
        new("--fight-loot-radius-m", "M", "The most metres from the mage a kill's corpse may lie for the loot step to open it (0 to 200, default 15; M5 7 F27, Lifestone's own: the den's rooms are small), and only with a clear line of sight to it (the fight's own shot line test): ACE's own MoveTo then walks the mage to it. A corpse beyond it, or out of sight, is left, named and counted."),
        new("--fight-loot-walk-s", "S", "The seconds the loot step waits for a corpse to open while ACE's MoveTo brings the mage (more than 0 to 200, default 20; M5 7 F27, Lifestone's own): a move-to that ends without the open (ACE's 15 s timeout, too busy, a stuck MoveTo) or runs past it leaves the corpse, named once as 'not reached: <why>', and the fight resumes."),
        new("--fight-loot-aggro-m", "M", "The metres around a corpse within which a living target creature of the ground makes the loot step put it off (0 to 200, default 6; 0 is off; M5 7 F27, the default lowered from 20 by the loot retry): the fight goes first. A creature that is attacking the mage now puts a corpse off too. A corpse put off stays queued and is retried when the fight has no target and nothing is in the way, until 270 s after the kill (ACE rots a monster corpse at 300 s); then it is given up as left to decay."),
        new("--fight-loot", "on|off", "Whether the fight loots its kills (default off; M5 item 3 m2, the owner's D38: the loot step is built whole and left off, so that turning it on is a switch). On: after a kill the fight finds the kill's corpse, opens it (M5 7 F27, closing m5-loot-no-walk: a corpse beyond reach is chosen only within --fight-loot-radius-m with a clear line of sight and no living target creature within --fight-loot-aggro-m of it; the open is sent as it is and ACE's own MoveTo walks the mage there, Player_Use.cs:184-206 and Player_Move.cs:37-96 @95ef426d; one that is not opened within --fight-loot-walk-s is left, named), keeps what the mage's rule says and closes it, then goes back to the tour. The rule keeps pyreals always and ranks the rest by value per burden (the description's Value, else an appraisal's), bounded by the load line (the inventory page's capacity) and the main pack's free slots; a corpse of the player's own is never looted (it is the death handler's). A corpse that does not appear, an open the server refuses and a full pack are named and the fight goes on. Off: nothing of this runs and the fight is exactly the one without it. The verdict ends with loot=on|off looted=<corpses> kept=<items> loot_value=<sum of the kept Values> and, with looting on, loot_opened=<corpses opened> loot_skipped_unreached=<left: out of radius, out of sight, move-to failed> loot_skipped_hostile=<left: a creature beside it> loot_walk_s=<seconds spent waiting on ACE's walk> and, last, corpses_opened=<corpses opened> loot_left_aggro=<times a corpse was put off by --fight-loot-aggro-m or an attacker; one corpse can count more than once> loot_left_decayed=<corpses given up, rotted or gone> (report-only)."),
        new("--fight-stamina-full", "P", "The stamina share, in percent (0 to 100, default 90; 0 is off), under which the fight loop refills the stamina with Revitalize Self (M5 7 F5, the owner's D88: in the fight the mana may run nearly empty and the stamina is kept near full). After a Stamina to Mana Self lands, and between kills when the mana pays a Revitalize Self and the next bolt, the highest Revitalize Self level the pack's scarabs and the mana allow is cast until the stamina is back at the share; a Stamina Potion is the fallback only when no Revitalize Self level is payable. 0 is the order of M5 item 1 exactly."),
        new("--fight-drain-under", "P", "The health share, in percent (0 to 100, default 50; 0 is off), under which the fight loop drains its target instead of casting a bolt (M5 7 F7, the owner's D88: the soak's level-80 mage has no Melee Defense and soaks the damage). With a living target in line and range the mage casts Drain Health Other, at the level the pick judges best at that moment (the expected heal at its current Life Magic against the target's Magic Defense, its mana cost and the health missing; a bolt when no level helps); with no target in reach it casts Heal Self at the highest level the pack's scarabs pay. It goes on until the health is at --fight-drain-until, then the bolts begin again."),
        new("--fight-drain-until", "P", "The safe health share, in percent (0 to 100, default 75, never under --fight-drain-under), at which the fight loop stops draining and casts bolts again (M5 7 F7, D88)."),
        new("--fight-emergency-floor", "P", "The least health share, in percent (0 to 100, default 60; 0 turns the emergency drain off), of the emergency line (M5 7 F16, the owner's D91: the fight never retreats on the den). The line is live: the larger of this floor and the damage the mage takes a second (the fight's measured rate, seeded from the first soak round's 2.3 a second) times three casts of the emergency drain plus --fight-emergency-margin of the maximum health. Under the line the mage casts Drain Health Other I (one gesture, no wind-up) at the living tusker in reach with the most health left, again at once, until --fight-emergency-safe; it outranks every other move."),
        new("--fight-emergency-safe", "P", "The health share, in percent (0 to 100, default 85, never under --fight-emergency-floor), at which the emergency drain ends and the fight's normal choices begin again (M5 7 F16, D91)."),
        new("--fight-emergency-margin", "P", "The margin, in percent of the maximum health (0 to 100, default 10), added to the damage expected during three casts of the emergency drain when the emergency line is worked out (M5 7 F16, D91)."),
        new("--fight-heal-damage-weight", "W", "The share (0 to 1, default 0.25) of the damage a Drain Health Other does to its target that counts as health a second when the fight weighs the drain against Heal Self (M5 7 F21, the owner's D92: a drain is cast only when it would help more than Heal Self, otherwise Heal Self; both are scored in health a second: the chance it lands times the health it gives, over its cast seconds plus its mana at the dance's seconds a mana point; a tie goes to Heal Self). Used by the emergency, the drain floor and the picker's drain as an attack."),
        new("--fight-ignore-line", null, "The fight loop casts at the nearest tusker whether or not a bolt can reach it (the pre-4.2 pick: from the arrival the three bolts hit the den's walls). Default: the loop picks the nearest tusker with a clear line from the caster (a sphere sweep through the den's collision) and walks on when none has one. This is the loop's own judgement, not a retail glitch fix: retail's client does not check a line before a war cast (ClientMagicSystem::CastSpell 11.6096 0x00568DE0), the player does."),
    ], OptionScenes.Main | OptionScenes.Headless);
}
